using System.Text;
using System.Text.Json.Nodes;
using System.Xml;
using UnattendLocal.Core;
using UnattendLocal.Desktop;

static class AutoPartitionTests {
 public static int Run(GeneratorService g){
  int count=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS V1.1 "+name);}
  InstallPlan Plan(){var p=InstallPlan.New();p.Users[0].Password="PartitionFixture1!";p.DiskMode=InstallationSettings.Wipe;p.TargetDiskId=2;return p;}
  string Xml(InstallPlan p){p.ConfirmWipeDisk=true;p.ConfirmImportedXmlRisk=true;return Encoding.UTF8.GetString(g.Generate(p));}
  void Reject(InstallPlan p,string name){try{g.Generate(p);}catch(ArgumentException){Check(true,name);return;}throw new Exception("Expected rejection: "+name);}
  string Strip(string xml){var d=XmlMerge.Read(xml);foreach(var c in d.SelectNodes("//comment()")!.Cast<XmlComment>().ToArray())c.ParentNode!.RemoveChild(c);return d.OuterXml;}
  var fresh=InstallPlan.New();Check(fresh.SystemPartitionSizeMB==null&&!fresh.PauseBeforeFormatting,"new options preserve default behavior");
  foreach(string arch in new[]{"amd64","x86","arm64"})foreach(string layout in new[]{"UEFI / GPT","BIOS / MBR"}){
   if(arch=="arm64"&&layout=="BIOS / MBR")continue;
   foreach(int? size in new int?[]{null,768,4096})foreach(bool pause in new[]{false,true}){
    var p=Plan();p.Architecture=arch;p.DiskLayout=layout;p.SystemPartitionSizeMB=size;p.PauseBeforeFormatting=pause;string source=Strip(Xml(p));var doc=XmlMerge.Read(source);var state=AutoPartitionSettings.Inspect(doc);string label=arch+layout+size+pause;
    Check(state is {Known:true,Values:{TargetDiskId:2}}&&state.Values.DiskLayout==layout&&AutoPartitionSettings.SystemSize(state.Values)==(size??(layout=="UEFI / GPT"?300:500)),"actual full partition flow recognized "+label);
    string command=state.Path!.InnerText;
    Check(command.Contains("echo create partition "+(layout=="UEFI / GPT"?"efi":"primary")+" size="+AutoPartitionSettings.SystemSize(p))&&command.Contains("label=Windows")&&command.Contains("label=Recovery")&&command.Contains("shrink minimum=1536 desired=1536"),"system size does not change Windows/recovery layout "+label);
    Check((command.Contains("&& pause &&"))==pause&&(!pause||command.IndexOf("&& pause &&",StringComparison.Ordinal)<command.IndexOf("diskpart.exe /s",StringComparison.Ordinal)),"pause precedes the destructive DiskPart call "+label);
    var imported=XmlPlanImport.Import(source,g);Check(imported.SystemPartitionSizeMB==size&&imported.PauseBeforeFormatting==pause&&!imported.ConfirmWipeDisk&&!imported.ConfirmImportedXmlRisk&&!imported.ImportedXml!.AutoPartitionReadOnly,"actual XML restores fields and clears consent "+label);
    Check(XmlMerge.Equal(doc.DocumentElement,XmlMerge.Read(Xml(imported)).DocumentElement),"unmodified native XML roundtrip "+label);
    var withSnapshot=XmlPlanImport.Import(Xml(p),g);Check(withSnapshot.SystemPartitionSizeMB==size&&withSnapshot.PauseBeforeFormatting==pause&&withSnapshot.TargetDiskId==2,"actual payload recovered with reversible snapshot "+label);
   }
  }
  foreach(string layout in new[]{"UEFI / GPT","BIOS / MBR"})foreach(int size in layout=="UEFI / GPT"?new[]{-1,0,299,8193,int.MaxValue}:new[]{-1,0,99,8193,int.MaxValue}){var p=Plan();p.DiskLayout=layout;p.SystemPartitionSizeMB=size;p.ConfirmWipeDisk=true;Reject(p,"invalid size rejected "+layout+size);}
  foreach(var pair in new[]{("UEFI / GPT",300),("UEFI / GPT",8192),("BIOS / MBR",100),("BIOS / MBR",8192)}){var p=Plan();p.DiskLayout=pair.Item1;p.SystemPartitionSizeMB=pair.Item2;Check(Xml(p).Length>0,"documented size boundary accepted "+pair);}
  var inactive=InstallPlan.New();inactive.Users[0].Password="Fixture1!";inactive.SystemPartitionSizeMB=-1;inactive.PauseBeforeFormatting=true;Check(!Xml(inactive).Contains("UnattendLocal-diskpart.txt"),"inactive options do not generate disk commands");
  var risk=Plan();risk.ConfirmWipeDisk=true;risk.ConfirmImportedXmlRisk=true;risk.SystemPartitionSizeMB=768;Check(!risk.ConfirmWipeDisk&&!risk.ConfirmImportedXmlRisk,"size edit clears dangerous-operation consent");Reject(risk,"size edit requires renewed disk consent");risk.ConfirmWipeDisk=true;risk.ConfirmImportedXmlRisk=true;risk.PauseBeforeFormatting=true;Check(!risk.ConfirmWipeDisk&&!risk.ConfirmImportedXmlRisk,"pause edit clears dangerous-operation consent");risk.ConfirmWipeDisk=true;risk.SystemPartitionSizeMB=768;Check(risk.ConfirmWipeDisk,"same size does not reset consent again");
  foreach(bool secrets in new[]{false,true}){var p=Plan();p.SystemPartitionSizeMB=768;p.PauseBeforeFormatting=true;p.ConfirmWipeDisk=true;var back=PlanStore.Deserialize(PlanStore.Serialize(p,secrets));Check(back.SystemPartitionSizeMB==768&&back.PauseBeforeFormatting&&!back.ConfirmWipeDisk&&back.Users[0].NeedsPassword==!secrets,"JSON preserves options independently from credentials "+secrets);}
  var seed=Plan();seed.SystemPartitionSizeMB=768;seed.PauseBeforeFormatting=true;string native=Strip(Xml(seed));var editable=XmlPlanImport.Import(native,g);editable.SystemPartitionSizeMB=1024;editable.PauseBeforeFormatting=false;editable.ComputerName="PARTITIONEDIT";var changed=XmlMerge.Read(Xml(editable));var updated=AutoPartitionSettings.Inspect(changed);Check(updated.Known&&AutoPartitionSettings.SystemSize(updated.Values!)==1024&&!updated.Values!.PauseBeforeFormatting&&XmlPlanImport.Import(changed.OuterXml,g).ComputerName=="PARTITIONEDIT","size/pause/independent edit exports and reimports");
  foreach(string mutation in new[]{"extra-command","wrong-target","wrong-phase","duplicate","different-path"}){
   var d=XmlMerge.Read(native);var state=AutoPartitionSettings.Inspect(d);var node=state.Path!;
   switch(mutation){case "extra-command":node.InnerText=node.InnerText.Replace("echo clean &","echo clean & echo list disk &");break;case "wrong-target":d.SelectSingleNode("//*[local-name()='InstallTo']/*[local-name()='DiskID']")!.InnerText="3";break;case "wrong-phase":var destination=d.SelectSingleNode("//*[local-name()='settings' and @pass='specialize']/*[local-name()='component' and @name='Microsoft-Windows-Deployment']/*[local-name()='RunSynchronous']")!;var moved=node.ParentNode!;moved.ParentNode!.RemoveChild(moved);moved.SelectSingleNode("*[local-name()='Order']")!.InnerText="99";destination.AppendChild(moved);break;case "duplicate":var copy=(XmlElement)node.ParentNode!.CloneNode(true);copy.SelectSingleNode("*[local-name()='Order']")!.InnerText="99";node.ParentNode.ParentNode!.AppendChild(copy);break;case "different-path":node.InnerText=node.InnerText.Replace("diskpart.exe /s X:","diskpart.exe /s Y:");break;}
   var p=XmlPlanImport.Import(d.OuterXml,g);Check(p.ImportedXml!.AutoPartitionReadOnly&&p.ImportedXml.Notices.Contains(AutoPartitionSettings.ReadOnlyNotice)&&AutoPartitionSettings.Summary(p).Contains("未完整识别")&&InstallationSettings.DiskSummary(p).Contains("核对原文"),"unknown partition payload protected "+mutation);
   if(p.ImportedXml.Blockers.Length==0){p.ComputerName="PRESERVEPART";var original=node.InnerText;Check(Xml(p).Contains("PRESERVEPART")&&XmlMerge.Read(Xml(p)).SelectNodes("//*[local-name()='Path']")!.Cast<XmlElement>().Any(e=>e.InnerText==original),"unknown command retained through unrelated edit "+mutation);p.PauseBeforeFormatting=!p.PauseBeforeFormatting;p.ConfirmWipeDisk=true;p.ConfirmImportedXmlRisk=true;Reject(p,"unknown partition cannot be overwritten "+mutation);}
  }
  foreach(string layout in new[]{"UEFI / GPT","BIOS / MBR"}){var explicitDefault=Plan();explicitDefault.DiskLayout=layout;explicitDefault.SystemPartitionSizeMB=layout=="UEFI / GPT"?300:500;var back=XmlPlanImport.Import(Xml(explicitDefault),g);Check(back.SystemPartitionSizeMB==explicitDefault.SystemPartitionSizeMB,"snapshot preserves explicit size even when it equals the layout default "+layout);}
  var pending=XmlPlanImport.Import(native,g);pending.ComputerName="PENDINGPART";var old=JsonNode.Parse(PlanStore.Serialize(pending,true))!.AsObject();old.Remove(nameof(InstallPlan.SystemPartitionSizeMB));old.Remove(nameof(InstallPlan.PauseBeforeFormatting));var b=XmlMerge.Read(pending.ImportedXml!.BaselineXml);var bs=AutoPartitionSettings.Inspect(b);bs.Values!.SystemPartitionSizeMB=null;bs.Values.PauseBeforeFormatting=false;bs.Path!.InnerText=AutoPartitionSettings.Command(bs.Values);old["ImportedXml"]!["BaselineXml"]=b.OuterXml;var migrated=PlanStore.Deserialize(old.ToJsonString());Check(migrated.SystemPartitionSizeMB==768&&migrated.PauseBeforeFormatting&&migrated.ComputerName=="PENDINGPART"&&AutoPartitionSettings.Inspect(XmlMerge.Read(Xml(migrated))).Known,"old imported plan migrates only new fields and preserves pending edits");
  var vm=new MainViewModel{Plan=Plan()};Check(vm.CanEditAutoPartition&&vm.AutoPartitionSummary.Contains("300"),"view model enables options and reflects default size");vm.Plan.SystemPartitionSizeMB=768;vm.Plan.PauseBeforeFormatting=true;Check(vm.AutoPartitionSummary.Contains("768")&&vm.ConfigurationSummary.Contains("暂停"),"summary follows size and pause changes");Recommendations.Apply(vm.Plan,"wired");Check(vm.Plan.DiskMode==InstallationSettings.Manual&&vm.Plan.SystemPartitionSizeMB==768&&vm.Plan.PauseBeforeFormatting&&!vm.CanEditAutoPartition,"recommended reset keeps inactive values but returns to manual disk mode");
  foreach(string term in new[]{"系统分区","EFI","SystemPartitionSizeMB","格式化前确认","PauseBeforeFormatting"})Check(SettingsSearchCatalog.Search(term).Any(r=>r.Target is "SystemPartitionSizeEditor" or "PauseBeforeFormattingCheck"),"new disk setting searchable "+term);
  return count;
 }
}
